// Conditions are explanatory: controls remain editable so a disabled effect can
// be prepared without altering the user's composition or enabling it silently.
export function controlCondition(s,key){
 const positive=k=>Math.abs(Number(s[k])||0)>1e-6||s.motions?.[k]?.enabled&&Math.abs(s.motions[k].amplitude||0)>1e-6;
 const need=(k,text)=>positive(k)?'':text;
 if(/^lights\.\d+\./.test(key)){const l=s.lights?.find(l=>String(l.id)===key.split('.')[1]);if(l?.enabled===false&&!key.endsWith('.enabled'))return 'Attiva questa luce per vedere il risultato.';}
 if(key.startsWith('finish')&&!['finishEnabled','finishCompare'].includes(key)){
  if(s.finishEnabled===false)return 'Attiva i filtri per vedere il risultato.';
  if(s.finishCompare)return 'Disattiva il confronto con l’originale per vedere i filtri.';
  const effect=[['Rgb','Rgb'],['Mosaic','Mosaic'],['Cell','Mosaic'],['Glyph','Glyph'],['Edge','Edge'],['Glitch','Glitch'],['Warp','Warp'],['Glass','Glass'],['Scan','Scan']].find(([prefix])=>key.startsWith('finish'+prefix));
  if(effect&&key!=='finish'+effect[1]&&!s['finish'+effect[1]])return 'Attiva questo filtro per vedere il risultato.';
 }
 if(key==='pSizeRatio')return need('pLargeCount','Scegli quanti granelli usano una misura diversa, in Distribuzione dimensioni.');
 if(key==='pSizeBias')return need('pSizeSpread','Aumenta Escursione dei diametri sopra zero.');
 if(key==='pNodeRatio')return need('pLinks','Attiva i fili: questo rapporto riguarda i granelli usati come nodi.');
 if(key==='pDistributionCells'&&Math.abs((s.pGrainSpacing??1)-1)+Math.abs((s.pGroupSpacing??1)-1)<1e-6)return 'Porta Dispersione o Distanza dei gruppi a un valore diverso da 1.';
 if(key==='pTrailDensity'&&(s.pTrailCount||0)*Math.max(1,(s.pTrailLength||0)/.2)*(1+(s.pTrailPersistence||0))<=4000)return 'La trama attuale non richiede compensazione: servono più scie, più lunghezza o più persistenza.';
 if(key==='finishScanFrequency')return need('finishScanWave','Aumenta Ondulazione sopra zero.');
 if(key==='finishGlyphSeed'&&!['finishGlyphRandom','finishGlyphFontRandom','finishGlyphSizeRandom','finishGlyphRotation','finishGlyphJitter'].some(positive))return 'Aumenta una variazione casuale dei caratteri, delle dimensioni, della rotazione o della posizione.';
 if(/^finishGlitch(Cycles|FlashMs|Duty|Softness|Rhythm|Scatter|Renew)$/.test(key)&&!s.finishGlitchAnimate)return 'Attiva l’animazione del glitch e premi Riproduci.';
 if(key==='environmentRefraction'&&!positive('transparency'))return 'Aumenta Trasparenza per vedere l’ambiente rifratto.';
 if(key==='environmentCycles'&&!s.environmentRotate)return 'Attiva Ruota ambiente e premi Riproduci.';
 if(key==='refraction'&&s.engine==='particles'&&(!positive('transparency')||!positive('pCaustic')))return 'Aumenta Trasparenza e Caustiche: nelle particelle questo indice regola la caustica.';
 if(key.startsWith('fil')&&!key.startsWith('film')&&key!=='filLength'&&!positive('filLength'))return 'Aggiungi filamenti aumentando Lunghezza in Forma.';
 if(key==='filPhase')return need('filWind','Aumenta Ampiezza di oscillazione delle punte sopra zero.');
 if(key.startsWith('petal')&&key!=='petalAmount'&&!positive('petalAmount'))return 'Aumenta Appendici in Forma → Petali e radici.';
 if(key==='petalDirectionSpread'&&!['petalCoil','petalReentry','petalCurl','petalWander'].some(positive))return 'Aggiungi una curva, una deviazione o un avvolgimento al percorso.';
 if(key==='motion'&&!Object.values(s.motions||{}).some(t=>t.enabled&&t.mode!=='cycle'&&Math.abs(t.amplitude)>1e-6)&&!s.lights?.some(l=>l.pulse?.enabled||l.orbit?.enabled&&l.orbit.mode!=='cycle'))return 'Attiva una traccia in oscillazione: l’ampiezza generale non modifica i giri completi.';
 return '';
}
export function controlHelp(key,engine){
 if(engine==='particles'&&key==='refraction')return 'Indice usato dalle caustiche delle particelle trasparenti. Richiede Trasparenza e Caustiche sopra zero e una materia non completamente metallica. Non rifrange lo sfondo come un solido di vetro.';
 if(engine==='solid'&&key==='guide.strength')return 'Intensità della deformazione lungo la curva. Attrazione richiama la superficie; repulsione la allontana. A 3, la repulsione svuota il tubo definito dal raggio.';
 if(engine==='solid'&&key==='guide.radius')return 'Raggio del tubo 3D che circonda la curva. Regola la zona di superficie influenzata, anche in profondità.';
 if(EXTRA_HELP[key])return EXTRA_HELP[key];
 if(key.startsWith('audio.'))return AUDIO_HELP[key.split('.').at(-1)];
 if(key.startsWith('body.'))return ({moveAmount:'Quanto il gesto sposta la forma rispetto alla posizione neutra. Zero disattiva lo spostamento.',turnAmount:'Quanto i movimenti e l’inclinazione della coppia A/B ruotano la forma. Zero disattiva la rotazione.',sizeAmount:'Quanto la distanza tra A e B modifica la dimensione. Fissa una posizione neutra con entrambe visibili.',gainX:'Amplifica gli spostamenti orizzontali della camera nel campo creativo.',gainY:'Amplifica gli spostamenti verticali.',offsetX:'Sposta il campo rispetto al centro della scena.',offsetY:'Alza o abbassa il campo rispetto al centro.',rotation:'Ruota gli assi del controllo per compensare la camera obliqua. La calibrazione metrica 4D resta separata.',smoothing:'Tempo di risposta del campo: valori alti rendono i movimenti più morbidi e ritardati.',deadzone:'Ignora oscillazioni molto piccole del punto misurato.',hold:'Dopo la perdita mantiene brevemente la forza prima di attenuarla.',fade:'Tempo impiegato per spegnere il campo dopo l’attesa.',mirrorX:'Inverte la direzione orizzontale.',mirrorY:'Inverte la direzione verticale.',show:'Mostra sulla scena i punti delle mani e delle braccia, esclusi dagli export.',loss:'Mantieni conserva il campo fermo fino al rientro. Attenua riduce progressivamente la forza.',target:'Campi piega particelle e fibre localmente. Sposta trascina tutta la creazione.',enabled:'Abilita l’influenza di questa parte del corpo.',mode:'Attira avvicina la materia al punto; respingi la allontana. Nello spostamento globale inverte il verso.',strength:'Intensità della risposta a questo punto del corpo.',radius:'Quanto lontano il punto del corpo influenza le particelle.',swirl:'Avvolge le particelle attorno al punto mobile.',z:'Profondità artistica del campo, impostata manualmente.'})[key.split('.').at(-1)];
 if(/^light2?Angle$/.test(key))return 'Sposta la sorgente attorno alla figura in orizzontale.';
 if(/^light2?Height$/.test(key))return 'Regola l’altezza della sorgente luminosa.';
 if(/^light2?Power$/.test(key))return LIGHT.power;
 if(/^light2?Size$/.test(key))return LIGHT.size;
 if(key.startsWith('force.'))return FORCE[key.slice(6)];
 if(key.startsWith('guide.'))return GUIDE[key.slice(6)];
 if(key.startsWith('motions.')||/^lights\.\d+\.(orbit|pulse)\./.test(key))return TRACK[key.split('.').at(-1)];
 if(key.startsWith('lights.'))return LIGHT[key.split('.').at(-1)];
 if(key.startsWith('palette.'))return 'Colore di base della materia. Modifica la casella o inserisci un codice esadecimale; luci e riflessi si aggiungono a questa palette.';
 return HELP[key];
}
